ini_set('display_errors', 1);
error_reporting(E_ALL);

/* ---------- Database configuration ---------- */
$db_host = 'localhost';     // e.g., '127.0.0.1' or 'localhost'
$db_name = 'your_database'; // replace with your database name
$db_user = 'your_user';     // replace with your DB username
$db_pass = 'your_pass';     // replace with your DB password

/* ---------- Helper: connect to DB with PDO ---------- */
function getPDO() {
    global $db_host, $db_name, $db_user, $db_pass;
    $dsn = "mysql:host=$db_host;dbname=$db_name;charset=utf8mb4";

    try {
        $pdo = new PDO($dsn, $db_user, $db_pass, [
            PDO::ATTR_ERRMODE            => PDO::ERRMODE_EXCEPTION,
            PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,
        ]);
        return $pdo;
    } catch (PDOException $e) {
        // In production, avoid echoing $e->getMessage().
        die("Database connection failed: " . $e->getMessage());
    }
}

/* ---------- Process form submission ---------- */
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    // Trim to remove surrounding whitespace
    $name = trim($_POST['name'] ?? '');
    $age  = trim($_POST['age'] ?? '');

    $errors = [];

    // Basic validation
    if ($name === '') {
        $errors[] = "Name cannot be empty.";
    }
    if ($age === '' || !ctype_digit($age) || (int)$age <= 0) {
        $errors[] = "Age must be a positive integer.";
    }

    if (empty($errors)) {
        try {
            $pdo = getPDO();

            // Prepared statement protects against SQL injection
            $stmt = $pdo->prepare('INSERT INTO users (name, age) VALUES (:name, :age)');
            $stmt->execute([
                ':name' => $name,
                ':age'  => (int)$age,
            ]);

